learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "EDX210",
      "rationale": "This comprehensive exam covers content from all five courses of the SCM MicroMasters series, providing a solid foundation for supply chain and operations management concepts."
    },
    {
      "step": 2,
      "course_id": "EDX2433",
      "rationale": "This course provides a decision-making framework for supply chain management, building on the foundational knowledge gained in the previous step."
    },
    {
      "step": 3,
      "course_id": "EDX2802",
      "rationale": "This course covers master control in supply chain management and logistics, introducing more advanced concepts and techniques for demand forecasting, lot sizing, and safety stock calculations."
    },
    {
      "step": 4,
      "course_id": "EDX1089",
      "rationale": "This course focuses on supply chain management tools and techniques, including aggregate planning, lean and continuous improvement tools, and sustainability considerations."
    },
    {
      "step": 5,
      "course_id": "EDX3401",
      "rationale": "This course provides a deeper understanding of global supply chains and how to leverage technology, analytics, and innovation to optimize processes and manage risks in volatile, uncertain, and complex environments."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX3264",
      "rationale": "Foundational course on nutrition science, covering the relationship between food and nutrition, and providing a solid understanding of nutritional assessment and education."
    },
    {
      "step": 2,
      "course_id": "EDX1100",
      "rationale": "Builds on the foundational course, providing a deeper understanding of nutrition and health, and equipping learners with the skills to conduct a motivational interview and nutritional assessment in a primary care setting."
    },
    {
      "step": 3,
      "course_id": "EDX1830",
      "rationale": "Progresses from the previous course, focusing on nutrition communication for health professionals, and providing learners with the skills to identify features of fad diets and common dietary misconceptions."
    },
    {
      "step": 4,
      "course_id": "EDX2270",
      "rationale": "Covers the role of dietary factors in the occurrence, progression, and treatment of cardiometabolic diseases, and provides learners with a deeper understanding of the biological processes contributing to cardiovascular disease, type 2 diabetes, and other cardiometabolic disorders."
    },
    {
      "step": 5,
      "course_id": "EDX2555",
      "rationale": "Builds on the previous course, focusing on food as medicine, and providing learners with the skills to identify how the Standard American Diet causes common diseases, and how to transition to a plant-based diet to prevent and reverse those diseases."
    }
  ]
}

